import sys
from collections import defaultdict

MOD = 10**9 + 9

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def mod_inverse(a, m):
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0
    while a > 1:
        # q is quotient
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    # Make x1 positive
    if x1 < 0:
        x1 += m0
    return x1

def count_permutations(n, freqs):
    total_permutations = factorial(n)
    for freq in freqs.values():
        total_permutations = (total_permutations * mod_inverse(factorial(freq), MOD)) % MOD
    return total_permutations

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    freqs = defaultdict(int)
    for num in a:
        freqs[num] += 1

    sorted_positions = set()

    for i in range(n):
        is_sorted = True
        for j in range(i + 1, n):
            if a[j] < a[i]:
                is_sorted = False
                break
        for j in range(i - 1, -1, -1):
            if a[j] > a[i]:
                is_sorted = False
                break
        if is_sorted:
            sorted_positions.add(i)

    unsorted_count = n - len(sorted_positions)

    if unsorted_count == 0:
